          : '';
      this.error.set((editing === null ? 'The claim could not be added.' : 'The claim could not be saved.') + why);
    } finally {
      this.submitting = false;
    }
  }
}

const pastOf: Record<ClaimAction, string> = {
  open: 'opened',
  settle: 'settled',
  void: 'voided',
  approve: 'approved',
  reject: 'rejected',
  resettle: 're-settled',
};

