  protected edit(claim: Claim): void {
    this.actionError.set(null);
    const sheet = this.session.sheet();
    if (!sheet) return;
    const refused = this.editRefusal(claim, null);
    if (refused !== null) {
      this.actionError.set({ id: claim.id, message: refused });
      return;
